.app-header {
  min-height: 62px; display: grid; grid-template-columns: 42px 1fr auto; gap: 10px;
  align-items: center; padding: 8px 14px; background: var(--primary); color: #fff;
  box-shadow: 0 4px 14px rgba(16,35,63,.18);
}
.app-menu-button { width:40px;height:40px;display:grid;place-content:center;gap:4px;border:0;border-radius:10px;background:transparent;color:#fff;cursor:pointer; }
.app-menu-button span { width:20px;height:2px;border-radius:9px;background:currentColor; }
.app-brand { min-width:0;display:flex;align-items:center;gap:8px;font-size:16px;letter-spacing:-.02em; }
.app-brand img { width:27px;height:27px;object-fit:contain;filter:brightness(0) invert(1); }
.app-role { font-size:10px;font-weight:800;opacity:.8;text-transform:uppercase;letter-spacing:.06em; }
.app-notification-button{position:relative;width:40px;height:40px;display:grid;place-items:center;padding:0;border:0;border-radius:10px;background:transparent;color:#fff;cursor:pointer}.app-notification-button:hover{background:rgba(255,255,255,.09)}.app-notification-button svg{width:22px;height:22px}.app-notification-badge{position:absolute;right:2px;top:2px;min-width:17px;height:17px;display:grid;place-items:center;padding:0 4px;border:2px solid var(--primary);border-radius:999px;background:#d92d20;color:#fff;font-size:9px;font-weight:900;line-height:1}

/* Barra de título: sem estilos exclusivos; utiliza a folha do componente principal. */

/* cliente.profissionais.perfil_publico · perfil integrado */
.professional-profile-page{width:min(100%,720px);margin:0 auto;padding:12px 14px 28px;display:grid;gap:12px;color:var(--text)}
.profile-card{background:var(--surface);border:1px solid var(--line);border-radius:15px;box-shadow:0 4px 12px rgba(15,23,42,.035)}
.profile-identity{display:grid;grid-template-columns:48px minmax(0,1fr) auto;gap:12px;align-items:center;padding:14px 16px}.profile-avatar{width:48px;height:48px;border-radius:13px;background:#e7f0ff;color:var(--primary);display:grid;place-items:center;font-weight:900}.profile-identity-copy h1{margin:0;color:var(--primary);font-size:15px}.profile-identity-copy p{margin:5px 0 0;color:var(--muted);font-size:11px;line-height:1.4}.profile-rating-badge{min-width:42px;height:30px;padding:0 9px;border-radius:999px;background:#ecfdf3;color:#087a4b;font-size:11px;font-weight:900;display:grid;place-items:center}
.profile-info{padding:8px 16px}.profile-info-row{display:grid;grid-template-columns:140px minmax(0,1fr);gap:14px;padding:11px 0;border-bottom:1px solid #edf1f5}.profile-info-row:last-child{border-bottom:0}.profile-info-row span{color:var(--muted);font-size:11px}.profile-info-row strong{color:var(--primary);font-size:11px;text-align:right;line-height:1.45}
.profile-summary{padding:15px 16px}.profile-eyebrow{display:block;margin:0 0 7px;color:var(--muted);font-size:9px;font-weight:900;letter-spacing:.08em;text-transform:uppercase}.profile-summary p{margin:0;color:var(--text);font-size:12px;line-height:1.55}
.profile-section-heading{display:flex;justify-content:space-between;align-items:flex-end;gap:12px;margin:4px 2px 0}.profile-section-heading h2{margin:0;color:var(--primary);font-size:15px}.profile-section-heading span{color:var(--muted);font-size:10px}
.contact-state-card{padding:14px 16px;display:grid;gap:12px}.contact-state-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.contact-state-head h3{margin:0;color:var(--primary);font-size:13px}.contact-state-head p{margin:4px 0 0;color:var(--muted);font-size:10px;line-height:1.45}.contact-status{white-space:nowrap;padding:6px 9px;border-radius:999px;font-size:9px;font-weight:900}.status-none{background:#edf4ff;color:var(--primary)}.status-pending{background:#fff7e8;color:#b76e00}.status-accepted{background:#ecfdf3;color:#087a4b}.status-closed{background:#f2f4f7;color:#475467}
.contact-actions{display:grid;gap:8px}.contact-actions.two{grid-template-columns:1fr 1fr}.profile-button{min-height:48px;border-radius:12px;padding:11px 14px;font-weight:900;font-size:11px;cursor:pointer}.profile-button.primary{border:0;background:var(--primary);color:#fff}.profile-button.secondary{border:1px solid var(--line);background:#fff;color:var(--primary)}.profile-button.warning{border:1px solid #f2ca84;background:#fffaf1;color:#8d5700}.profile-button.whatsapp{border:0;background:#20c96b;color:#fff}.profile-button.call{border:0;background:#2f6fcb;color:#fff}.profile-button[disabled]{opacity:.55;cursor:not-allowed}
.contact-note{display:flex;gap:8px;align-items:flex-start;padding:9px 10px;border-radius:10px;background:#f8fafc;color:var(--muted)}.contact-note>span{width:6px;height:6px;border-radius:50%;background:#94a3b8;margin-top:4px;flex:0 0 auto}.contact-note p{margin:0;font-size:9px;line-height:1.4}
.review-overview{padding:15px 16px;display:grid;gap:14px}.review-score-line{display:flex;align-items:center;gap:12px}.review-score-line>strong{font-size:28px;font-weight:900;color:var(--primary)}.review-stars{color:#e3a008;letter-spacing:1px;font-size:16px}.review-stars.small{font-size:12px}.review-score-line small{display:block;margin-top:2px;color:var(--muted);font-size:10px}.review-metric{display:grid;grid-template-columns:120px 1fr 36px;gap:10px;align-items:center}.review-metric>span,.review-metric>strong{font-size:11px}.review-metric>span{color:var(--muted)}.review-metric>strong{color:var(--primary);text-align:right}.review-track{height:7px;border-radius:999px;background:#e9eef4;overflow:hidden}.review-fill{display:block;height:100%;border-radius:999px;background:var(--primary)}.review-fill-98{width:98%}.review-fill-94{width:94%}.review-disclaimer{padding:13px 16px;color:var(--muted);font-size:10px;line-height:1.5}.review-list{display:grid;gap:9px}.review-item{padding:14px 16px}.review-item-head{display:flex;justify-content:space-between;gap:12px;align-items:center}.review-item-head strong{font-size:11px;color:var(--primary)}.review-item-head span{font-size:9px;color:var(--muted)}.review-item .review-stars{margin:6px 0 7px}.review-item p{margin:0;color:var(--text);font-size:11px;line-height:1.5}
.profile-footer-actions{display:grid;gap:9px;margin-top:2px}.profile-helper{display:flex;align-items:flex-start;gap:8px;color:var(--muted);padding:0 3px}.profile-helper>span{width:6px;height:6px;border-radius:50%;background:var(--gold);margin-top:4px;flex:0 0 auto}.profile-helper p{margin:0;font-size:10px;line-height:1.45}.op-toast{position:fixed;left:50%;bottom:22px;z-index:50;transform:translate(-50%,20px);opacity:0;pointer-events:none;transition:.2s;background:#101828;color:#fff;padding:11px 15px;border-radius:10px;font-size:11px;box-shadow:0 10px 25px rgba(0,0,0,.2)}.op-toast.show{opacity:1;transform:translate(-50%,0)}
@media(max-width:560px){.professional-profile-page{padding:9px 10px 22px;gap:9px}.profile-identity{grid-template-columns:38px minmax(0,1fr) auto;padding:11px 12px}.profile-avatar{width:38px;height:38px;border-radius:10px;font-size:11px}.profile-identity-copy h1{font-size:12px}.profile-identity-copy p{font-size:9px}.profile-rating-badge{min-width:36px;height:24px;font-size:9px}.profile-info{padding:0 11px}.profile-info-row{display:block;padding:9px 0}.profile-info-row span{display:block;margin-bottom:4px;font-size:8px;font-weight:900;text-transform:uppercase}.profile-info-row strong{display:block;text-align:left;font-size:10px}.profile-summary{padding:11px 12px}.profile-summary p{font-size:10px}.profile-section-heading h2{font-size:13px}.contact-state-card{padding:11px 12px}.contact-state-head h3{font-size:11px}.contact-state-head p{font-size:9px}.contact-status{font-size:8px}.contact-actions.two{grid-template-columns:1fr}.profile-button{min-height:47px;font-size:10px}.review-overview{padding:12px}.review-score-line>strong{font-size:23px}.review-metric{grid-template-columns:92px 1fr 30px;gap:7px}.review-metric>span,.review-metric>strong{font-size:9px}.review-item{padding:11px 12px}.review-item p{font-size:10px}.profile-helper p{font-size:9px}}
/* Controle temporário de simulação dos estados do perfil. Não pertence ao app final. */
.profile-simulation-zone{margin-top:8px;padding-top:2px;display:grid;justify-items:center;gap:9px;text-align:center}
.profile-simulation-separator{width:100%;height:1px;background:var(--line);margin-bottom:3px}
.profile-simulation-label{margin:0;color:var(--muted);font-size:8px;font-weight:900;letter-spacing:.07em;line-height:1.4}
.profile-simulation-trigger{border:1px dashed #b88932;background:#fffaf0;color:#7a5614;border-radius:9px;padding:8px 14px;font-size:9px;font-weight:900;cursor:pointer}
.profile-simulation-trigger:hover{background:#fff4dc}
.contact-simulation-modal{position:fixed;inset:0;z-index:10050;display:flex;align-items:center;justify-content:center;padding:18px}
.contact-simulation-modal[hidden]{display:none!important}
.contact-simulation-backdrop{position:absolute;inset:0;background:rgba(15,23,42,.58)}
.contact-simulation-dialog{position:relative;z-index:1;width:min(100%,480px);max-height:min(86vh,640px);overflow:auto;background:#fff;border-radius:18px;padding:18px;box-shadow:0 24px 70px rgba(0,0,0,.28)}
.contact-simulation-head{display:flex;justify-content:space-between;align-items:flex-start;gap:14px}
.contact-simulation-head h2{margin:3px 0 0;color:var(--primary);font-size:16px}
.simulation-eyebrow{font-size:8px;font-weight:900;letter-spacing:.08em;color:#8d641b}
.contact-simulation-x{border:0;background:#f3f5f8;color:#344054;width:34px;height:34px;border-radius:10px;font-size:20px;line-height:1;cursor:pointer}
.contact-simulation-explainer{margin:12px 0;padding:10px 11px;border:1px solid #f0d59c;background:#fffaf0;border-radius:10px;color:#6f551d;font-size:10px;line-height:1.5}
.contact-simulation-options{border:0;padding:0;margin:0;display:grid;gap:8px}
.contact-simulation-options legend{padding:0 0 7px;color:#344054;font-size:10px;font-weight:900}
.contact-simulation-options label{display:flex;align-items:flex-start;gap:9px;padding:10px;border:1px solid var(--line);border-radius:11px;cursor:pointer;background:#fff}
.contact-simulation-options label:has(input:checked){border-color:#b88932;background:#fffaf0}
.contact-simulation-options input{margin-top:2px}
.contact-simulation-options span{display:grid;gap:2px}
.contact-simulation-options strong{font-size:10px;color:#1d2939}
.contact-simulation-options small{font-size:9px;line-height:1.4;color:var(--muted)}
.contact-simulation-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:14px}
@media(max-width:560px){.profile-simulation-zone{margin-top:6px;gap:8px}.profile-simulation-label{font-size:7px}.profile-simulation-trigger{font-size:8px;padding:7px 12px}.contact-simulation-dialog{padding:15px;border-radius:15px}.contact-simulation-actions{grid-template-columns:1fr}.contact-simulation-head h2{font-size:14px}}

.prototype-drawer {
  position: fixed;
  z-index: 40;
  inset: 0;
  display: none;
}

.prototype-drawer.open { display: block; }

.drawer-backdrop {
  position: absolute;
  inset: 0;
  width: 100%;
  border: 0;
  background: rgba(7, 16, 30, .60);
}

.drawer-panel {
  position: absolute;
  inset: 0 auto 0 0;
  width: min(80vw, 360px);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  background: #3b4a7d;
  color: #fff;
  box-shadow: 12px 0 30px rgba(0, 0, 0, .32);
}

.drawer-top {
  flex: 0 0 auto;
  min-height: 106px;
  padding: 30px 22px 20px;
  display: flex;
  align-items: center;
}

.drawer-identity {
  min-width: 0;
  display: flex;
  gap: 14px;
  align-items: center;
}

.drawer-avatar {
  flex: 0 0 56px;
  width: 56px;
  height: 56px;
  display: grid;
  place-items: center;
  border: 2px solid rgba(255, 255, 255, .20);
  border-radius: 50%;
  background: #dbeafe;
  color: #1e3a8a;
  font-size: 20px;
  font-weight: 800;
}

.drawer-profile { min-width: 0; }
.drawer-profile strong,
.drawer-profile small { display: block; }
.drawer-profile strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 16px;
  font-weight: 600;
}
.drawer-profile small {
  margin-top: 2px;
  color: #bfdbfe;
  font-size: 11px;
  font-weight: 400;
  text-transform: lowercase;
}

.drawer-online {
  flex: 0 0 auto;
  width: calc(100% - 44px);
  margin: 0 22px 10px;
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 10px;
  align-items: center;
  border: 1px solid rgba(255, 255, 255, .18);
  border-radius: 10px;
  padding: 10px 12px;
  background: rgba(255, 255, 255, .08);
  color: #fff;
  text-align: left;
  cursor: pointer;
}
.drawer-online-copy strong,
.drawer-online-copy small { display: block; }
.drawer-online-copy strong { font-size: 13px; }
.drawer-online-copy small { margin-top: 2px; color: #bfdbfe; font-size: 10px; }
.online-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #4ade80;
  box-shadow: 0 0 0 4px rgba(74, 222, 128, .14);
}
.drawer-online.is-offline .online-dot { background: #98a2b3; box-shadow: none; }
.online-switch { position: relative; width: 38px; height: 22px; border-radius: 999px; background: #22c55e; }
.online-switch b { position: absolute; top: 3px; right: 3px; width: 16px; height: 16px; border-radius: 50%; background: #fff; }
.drawer-online.is-offline .online-switch { background: #64748b; }
.drawer-online.is-offline .online-switch b { right: 19px; }

.drawer-nav {
  flex: 1 1 auto;
  min-height: 0;
  display: block;
  margin: 0;
  padding: 0 0 8px;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, .35) transparent;
}
.drawer-nav::-webkit-scrollbar { width: 5px; }
.drawer-nav::-webkit-scrollbar-thumb { border-radius: 999px; background: rgba(255, 255, 255, .35); }

.drawer-nav button {
  width: 100%;
  min-height: 51px;
  padding: 14px 22px;
  border: 0;
  border-bottom: 1px solid rgba(255, 255, 255, .10);
  background: transparent;
  color: #f8fafc;
  display: flex;
  gap: 15px;
  align-items: center;
  text-align: left;
  font-size: 14px;
  font-weight: 400;
  cursor: pointer;
}
.drawer-nav button:hover { background: rgba(255, 255, 255, .08); }
.drawer-icon { flex: 0 0 20px; width: 20px; height: 20px; color: #aebee5; }

.drawer-footer {
  flex: 0 0 auto;
  margin-top: 0;
  padding: 16px 22px 30px;
  display: flex;
  flex-direction: column;
  gap: 22px;
  background: rgba(0, 0, 0, .10);
}
.drawer-footer-top { display: flex; justify-content: space-between; gap: 12px; align-items: center; }
.drawer-logout {
  min-height: 32px;
  padding: 0;
  border: 0;
  background: transparent;
  color: #f8fafc;
  display: flex;
  gap: 10px;
  align-items: center;
  font-size: 14px;
  cursor: pointer;
}
.drawer-logout svg { width: 18px; height: 18px; color: #aebee5; }
.drawer-footer small { color: #aebee5; font-size: 10px; }
.drawer-emergency {
  min-height: 41px;
  border: 1px solid rgba(255, 255, 255, .54);
  border-radius: 999px;
  background: transparent;
  color: #fff;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}
.drawer-emergency:hover { background: rgba(255, 255, 255, .08); }

@media (max-width: 420px) {
  .drawer-panel { width: 80vw; }
  .drawer-top { padding-top: 24px; }
}
